const path=require('node:path'),{spawn,execFileSync}=require('node:child_process'),{valid,candidates,rank}=require('./hancom-discovery.cjs');
const roots=[process.env['ProgramFiles(x86)']||'C:\\Program Files (x86)',process.env.ProgramFiles||'C:\\Program Files'].map(folder=>path.join(folder,'Hnc'));
function registered(){const files=[];for(const hive of ['HKCU','HKLM'])for(const view of ['32','64']){try{const output=execFileSync(path.join(process.env.SystemRoot||'C:\\Windows','System32/reg.exe'),['query',hive+'\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\App Paths\\Hwp.exe','/ve','/reg:'+view],{windowsHide:true,encoding:'utf8',stdio:['ignore','pipe','ignore'],timeout:1500});const value=output.match(/REG_(?:EXPAND_)?SZ\s+(.+)/)?.[1]?.trim();if(value){const expanded=value.replace(/%([^%]+)%/g,(_,name)=>process.env[name]||'%'+name+'%').replace(/^"|"$/g,'');if(valid(expanded))files.push(path.resolve(expanded));}}catch{}}return files;}
function discoverHancom(){const override=process.env.NARAE_HWP_EXE;if(override){if(!valid(override))return {hangul:null,error:'NARAE_HWP_EXE 경로에서 Hwp.exe를 찾을 수 없습니다.'};return {hangul:path.resolve(override),source:'override'};}const files=[...new Set([...candidates(roots),...registered()])].sort((a,b)=>rank(b)-rank(a)||b.localeCompare(a));return {hangul:files[0]||null,candidates:files};}
function nativeKind(file){return /\.hwpx?$/i.test(file)?'hangul':null;}
function openHancom(file){if(!nativeKind(file))return false;const executable=discoverHancom().hangul;if(!executable)throw new Error('한컴오피스 한글을 먼저 설치하세요.');return new Promise((resolve,reject)=>{const child=spawn(executable,[file],{cwd:path.dirname(executable),windowsHide:true,detached:true,stdio:'ignore'});child.once('error',reject);child.once('spawn',()=>{child.unref();resolve(true);});});}
module.exports={discoverHancom,nativeKind,openHancom};
